/**
 * test-retrieval.js
 *
 * Retrieval-only evaluation for whichever experiment is currently loaded
 * in MongoDB. Runs all 36 in-scope evaluation questions through the
 * existing retrieval service and records Hit@1/3/5 metrics.
 *
 * NO GENERATION — does not call the LLM, does not consume generation quota.
 * Query embeddings are generated by the Gemini embedding model (small cost).
 *
 * Usage:
 *   node evaluation/experiments/test-retrieval.js --experiment chunk-300
 *   node evaluation/experiments/test-retrieval.js --experiment chunk-800
 *
 * Output:
 *   evaluation/experiments/results/<id>/retrieval-results.json
 *   evaluation/experiments/results/<id>/retrieval-report.md
 */

require('dotenv').config();

const fs   = require('fs');
const path = require('path');

const { retrieve }        = require('../../backend/src/services/retrieval.service');
const { closeConnection } = require('../../backend/src/config/mongodb');

// ---------------------------------------------------------------------------
// PATHS
// ---------------------------------------------------------------------------
const PROJECT_ROOT    = path.resolve(__dirname, '../..');
const QUESTIONS_PATH  = path.resolve(PROJECT_ROOT, 'evaluation/questions.json');
const CONFIG_PATH     = path.resolve(__dirname, 'config.json');

// ---------------------------------------------------------------------------
// ARGS
// ---------------------------------------------------------------------------
function parseArgs() {
  const args = process.argv.slice(2);
  let experiment = null;
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--experiment' && args[i + 1]) experiment = args[++i];
  }
  return { experiment };
}

// ---------------------------------------------------------------------------
// PERCENTILE / AVERAGE helpers
// ---------------------------------------------------------------------------
function percentile(sorted, p) {
  if (!sorted.length) return null;
  const idx = (p / 100) * (sorted.length - 1);
  const lo  = Math.floor(idx);
  const hi  = Math.ceil(idx);
  return lo === hi ? sorted[lo] : sorted[lo] + (sorted[hi] - sorted[lo]) * (idx - lo);
}
function avg(arr) {
  return arr.length ? arr.reduce((s, v) => s + v, 0) / arr.length : null;
}
function r2(n) { return n === null ? null : Math.round(n * 100) / 100; }

// ---------------------------------------------------------------------------
// GENERATE RETRIEVAL REPORT MD
// ---------------------------------------------------------------------------
function buildReport(experiment, config, results, metrics) {
  const lines = [];
  lines.push(`# Retrieval-Only Evaluation — ${experiment.id}`);
  lines.push('');
  lines.push('> This report covers retrieval quality only. No LLM generation was run.');
  lines.push('');
  lines.push('## Experiment Configuration');
  lines.push('');
  lines.push(`| Parameter | Value |`);
  lines.push(`|-----------|-------|`);
  lines.push(`| Experiment | ${experiment.id} |`);
  lines.push(`| Chunk size | ${experiment.chunkSize} chars |`);
  lines.push(`| Overlap | ${experiment.overlap} chars |`);
  lines.push(`| Number of chunks | ${experiment.id === 'chunk-300' ? 860 : 300} |`);
  lines.push(`| Embedding model | ${config.sharedConfig.embeddingModel} |`);
  lines.push(`| Embedding dimension | 3072 |`);
  lines.push(`| Vector index | vector_index |`);
  lines.push(`| Top-K | ${config.sharedConfig.topK} |`);
  lines.push(`| Questions evaluated | ${metrics.total} in-scope |`);
  lines.push('');

  lines.push('## Retrieval Metrics');
  lines.push('');
  lines.push(`| Metric | Value | Raw |`);
  lines.push(`|--------|-------|-----|`);
  lines.push(`| Hit@1 | ${(metrics.hit1 * 100).toFixed(1)}% | ${metrics.hit1_raw}/${metrics.total} |`);
  lines.push(`| Hit@3 | ${(metrics.hit3 * 100).toFixed(1)}% | ${metrics.hit3_raw}/${metrics.total} |`);
  lines.push(`| Hit@5 | ${(metrics.hit5 * 100).toFixed(1)}% | ${metrics.hit5_raw}/${metrics.total} |`);
  lines.push('');

  lines.push('## Latency');
  lines.push('');
  lines.push(`| Metric | Value |`);
  lines.push(`|--------|-------|`);
  lines.push(`| Average | ${Math.round(metrics.latency.avg)}ms |`);
  lines.push(`| P50 (median) | ${Math.round(metrics.latency.p50)}ms |`);
  lines.push(`| P95 | ${Math.round(metrics.latency.p95)}ms |`);
  lines.push('');

  lines.push('## Per-Question Results');
  lines.push('');
  lines.push('| ID | Category | Hit@1 | Hit@3 | Hit@5 | Top Score | Expected Source |');
  lines.push('|----|----------|-------|-------|-------|-----------|----------------|');
  for (const r of results) {
    const topScore = r.retrievedSources.length ? r.retrievedSources[0].score.toFixed(4) : 'N/A';
    lines.push(`| ${r.id} | ${r.category} | ${r.hit1 ? '✅' : '❌'} | ${r.hit3 ? '✅' : '❌'} | ${r.hit5 ? '✅' : '❌'} | ${topScore} | ${r.expectedSource} |`);
  }
  lines.push('');

  lines.push('## Misses (expectedSource not in Top-5)');
  lines.push('');
  const misses = results.filter(r => !r.hit5);
  if (misses.length === 0) {
    lines.push('No misses — expectedSource found in Top-5 for all questions.');
  } else {
    lines.push('| ID | Question | Expected | Top Retrieved |');
    lines.push('|----|----------|----------|--------------|');
    for (const r of misses) {
      const topDoc = r.retrievedSources.length ? r.retrievedSources[0].documentId : 'none';
      lines.push(`| ${r.id} | ${r.question.slice(0, 50)}... | ${r.expectedSource} | ${topDoc} |`);
    }
  }
  lines.push('');

  lines.push('## Limitations');
  lines.push('');
  lines.push('- Hit@K uses exact `documentId` matching against `expectedSource`.');
  lines.push('- A question may be answerable from multiple documents; only one is marked as `expectedSource`.');
  lines.push('  Hit@K may undercount valid retrievals for ambiguous questions.');
  lines.push('- This report covers retrieval only. Answer quality requires LLM generation (Phase 10D-5).');
  lines.push('- Comparison with chunk-800 should only be made after both configurations are fully evaluated.');
  lines.push('');

  return lines.join('\n');
}

// ---------------------------------------------------------------------------
// MAIN
// ---------------------------------------------------------------------------
async function main() {
  const { experiment: expId } = parseArgs();

  if (!expId) {
    console.error('Usage: node test-retrieval.js --experiment <chunk-300|chunk-800>');
    process.exit(1);
  }

  const config     = JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf8'));
  const experiment = config.experiments.find(e => e.id === expId);
  if (!experiment) {
    console.error(`Unknown experiment: "${expId}". Available: ${config.experiments.map(e => e.id).join(', ')}`);
    process.exit(1);
  }

  const topK        = config.sharedConfig.topK;
  const questions   = JSON.parse(fs.readFileSync(QUESTIONS_PATH, 'utf8'));
  const inScope     = questions.filter(q => q.scope === 'in_scope');
  const resultsDir  = path.resolve(PROJECT_ROOT, experiment.resultsDir);

  fs.mkdirSync(resultsDir, { recursive: true });

  console.log('=== Retrieval-Only Evaluation ===\n');
  console.log(`Experiment : ${experiment.id} (${experiment.label})`);
  console.log(`Questions  : ${inScope.length} in-scope`);
  console.log(`Top-K      : ${topK}`);
  console.log('');

  const results = [];
  const latencies = [];

  for (let i = 0; i < inScope.length; i++) {
    const q = inScope[i];
    process.stdout.write(`[${i + 1}/${inScope.length}] ${q.id} ... `);

    const start = Date.now();
    let retrieved;
    try {
      retrieved = await retrieve(q.question, topK);
    } catch (err) {
      console.log(`ERROR: ${err.message.slice(0, 60)}`);
      results.push({
        id: q.id, category: q.category, question: q.question,
        expectedSource: q.expectedSource,
        retrievedSources: [], hit1: false, hit3: false, hit5: false,
        latencyMs: Date.now() - start, error: err.message,
      });
      continue;
    }
    const latencyMs = Date.now() - start;
    latencies.push(latencyMs);

    const docIds = retrieved.map(r => r.documentId);
    const hit1   = docIds.slice(0, 1).includes(q.expectedSource);
    const hit3   = docIds.slice(0, 3).includes(q.expectedSource);
    const hit5   = docIds.slice(0, 5).includes(q.expectedSource);

    results.push({
      id:              q.id,
      category:        q.category,
      question:        q.question,
      expectedSource:  q.expectedSource,
      retrievedSources: retrieved.map(r => ({
        chunkId:    r.chunkId,
        documentId: r.documentId,
        title:      r.title,
        sourceUrl:  r.sourceUrl,
        score:      r.score,
      })),
      hit1,
      hit3,
      hit5,
      latencyMs,
    });

    const mark = hit5 ? (hit1 ? '✅H1' : hit3 ? '✅H3' : '✅H5') : '❌miss';
    console.log(`${mark}  ${latencyMs}ms  top=${docIds[0]}`);
  }

  // ---------------------------------------------------------------------------
  // METRICS
  // ---------------------------------------------------------------------------
  const n      = results.filter(r => !r.error).length;
  const h1_raw = results.filter(r => r.hit1).length;
  const h3_raw = results.filter(r => r.hit3).length;
  const h5_raw = results.filter(r => r.hit5).length;
  const sorted = [...latencies].sort((a, b) => a - b);

  const metrics = {
    total:    inScope.length,
    success:  n,
    hit1:     r2(h1_raw / n), hit1_raw: h1_raw,
    hit3:     r2(h3_raw / n), hit3_raw: h3_raw,
    hit5:     r2(h5_raw / n), hit5_raw: h5_raw,
    latency: {
      avg: r2(avg(sorted)),
      p50: r2(percentile(sorted, 50)),
      p95: r2(percentile(sorted, 95)),
      min: sorted[0]  ?? null,
      max: sorted[sorted.length - 1] ?? null,
    },
  };

  // ---------------------------------------------------------------------------
  // SAVE
  // ---------------------------------------------------------------------------
  const outputJson = path.join(resultsDir, 'retrieval-results.json');
  const outputMd   = path.join(resultsDir, 'retrieval-report.md');

  fs.writeFileSync(outputJson, JSON.stringify({ experiment: expId, metrics, results }, null, 2));
  fs.writeFileSync(outputMd,   buildReport(experiment, config, results, metrics));

  // ---------------------------------------------------------------------------
  // PRINT SUMMARY
  // ---------------------------------------------------------------------------
  console.log('\n========================================');
  console.log(`RETRIEVAL RESULTS — ${experiment.id}`);
  console.log('========================================');
  console.log(`Questions     : ${n}/${inScope.length}`);
  console.log(`Hit@1         : ${(metrics.hit1 * 100).toFixed(1)}%  (${h1_raw}/${n})`);
  console.log(`Hit@3         : ${(metrics.hit3 * 100).toFixed(1)}%  (${h3_raw}/${n})`);
  console.log(`Hit@5         : ${(metrics.hit5 * 100).toFixed(1)}%  (${h5_raw}/${n})`);
  console.log(`Latency avg   : ${Math.round(metrics.latency.avg)}ms`);
  console.log(`Latency P50   : ${Math.round(metrics.latency.p50)}ms`);
  console.log(`Latency P95   : ${Math.round(metrics.latency.p95)}ms`);
  console.log(`Results saved : ${outputJson}`);
  console.log(`Report saved  : ${outputMd}`);
  console.log('========================================\n');
}

main()
  .catch(err => { console.error('Error:', err.message); process.exit(1); })
  .finally(() => closeConnection());
